using System;using System.Collections.Generic;using Ashfall.Core;using Ashfall.Modules.WeaponHandling;
namespace Ashfall.Integration.Playable.HandsWeapons {
 public sealed class R24DualDefinition {
  public readonly string Id,CatalogId,AmmoFamily,Label;public readonly int CatalogIndex,Stars,Capacity,Pellets;public readonly float Body,Head,Interval,Scale;public bool Automatic{get{return Id=="uzis";}}
  public R24DualDefinition(string id,int stars=1){if(id!="uzis"&&id!="matadors"||stars<1||stars>5)throw new ArgumentException("Actual dual profile/rarity");Id=id;Stars=stars;bool u=id=="uzis";CatalogId=u?"twin_meridian":"twin_matadors";CatalogIndex=u?11:12;Label=u?"DUAL UZIS":"DUAL MATADORS";AmmoFamily=u?"smg":"shells";Capacity=u?16+4*stars:8;Pellets=u?1:8;Body=Head=u?14:16+4*stars;Interval=u?1f/13:1f/(3.125f*1.2f);Scale=u?.65436f:.9f;}
  public Float3 Muzzle{get{return new Float3(0,.045f,Automatic?.46f:.37f);}}public static readonly Float3 SpinPivot=new Float3(0,-.057f,-.025f);public const float SpinSeconds=.36f;
 }
 public struct R24DualHandInput {public bool Tracked,InputReady,Climbing,Reserved,TriggerClick;public float Trigger;public Float3 FlickPoint,Forward;public R23ShotPose FiringPose;public bool Pressed{get{return Trigger>.65f||TriggerClick;}}}
 public struct R24DualFrame {public long Sequence;public float DeltaSeconds;public bool Enabled,Paused,Focused,HeadObstructed,DesktopReload;public int DominantHand;public R24DualHandInput Left,Right;public R24DualHandInput Hand(int physical){return physical==0?Left:Right;}}
 public struct R24DualHandState {public int Loaded,Capacity,PhysicalHand;public long Shots;public bool NeedsAmmo,RequiresTriggerRelease;public float Cooldown,SpinElapsed;}
 public sealed class R24DualVolley {
  readonly Float3[] directions;readonly R24DualOwner owner;internal readonly long Epoch;public readonly string InstanceId,Profile;public readonly CommandContext Command;public readonly int Side,PhysicalHand;public readonly long Serial;public readonly R23ShotPose Pose;public readonly float BodyPerPellet,HeadPerPellet;
  internal R24DualVolley(R24DualOwner o,CommandContext c,int side,int hand,long serial,R23ShotPose pose,long epoch){owner=o;Epoch=epoch;InstanceId=o.InstanceId;Profile=o.Definition.Id;Command=c;Side=side;PhysicalHand=hand;Serial=serial;Pose=pose;BodyPerPellet=o.Definition.Body/o.Definition.Pellets;HeadPerPellet=o.Definition.Head/o.Definition.Pellets;directions=new Float3[o.Definition.Pellets];for(int i=0;i<directions.Length;i++){double angle=Math.PI*2*i/8,radius=directions.Length==1?0:Math.Tan(5*Math.PI/180)*(i%2==0?.4:1);var v=R23WeaponPoseMath.Add(pose.Forward,R23WeaponPoseMath.Add(R23WeaponPoseMath.Scale(pose.Right,(float)(Math.Cos(angle)*radius)),R23WeaponPoseMath.Scale(pose.Up,(float)(Math.Sin(angle)*radius))));directions[i]=R23WeaponPoseMath.Scale(v,1/(float)Math.Sqrt(R23WeaponPoseMath.Dot(v,v)));}}
  public int PelletCount{get{return directions.Length;}}public Float3 Direction(int pellet){return directions[pellet];}internal bool Claim(){return owner.Claim(this);}
 }
 public sealed class R24DualStep {public readonly R24DualVolley Dominant,Other;public readonly string DominantReload,OtherReload;internal R24DualStep(R24DualVolley a,R24DualVolley b,string ra,string rb){Dominant=a;Other=b;DominantReload=ra;OtherReload=rb;}}
 public sealed class R24DualOwner {
  sealed class Gun {internal int Loaded;internal long Shots,Committed;internal bool NeedRelease=true,SemiArmed=true;internal float Cooldown,Spin=.36f;internal readonly Flick Flick=new Flick();}
  sealed class Flick {
   struct Sample{internal Float3 Point,Forward;internal float Time;}readonly Sample[] history=new Sample[64];int start,count;float clock,neutral;bool ready;
   internal void Reset(){start=count=0;neutral=0;ready=false;}
   internal bool Step(R24DualHandInput h,float dt,int ammo,float spin){if(!h.FlickPoint.IsFinite||!h.Forward.IsFinite||dt<=0||dt>.15f){Reset();return false;}clock+=dt;Sample newest=count==0?new Sample():history[(start+count-1)%64];float distance=count==0?0:Length(Sub(h.FlickPoint,newest.Point));if(count>0&&distance>.7f){Reset();return false;}float angle=count==0?0:Angle(h.Forward,newest.Forward);if((!h.Pressed||ammo==0)&&distance/dt<1.1f&&angle/dt<5&&spin>=.36f){neutral+=dt;if(neutral>=.07f)ready=true;}else neutral=0;
    while(count>0&&clock-history[start].Time>.34f){start=(start+1)%64;count--;}
    if(ready&&(!h.Pressed||ammo==0))for(int i=0;i<count;i++){var first=history[(start+i)%64];float elapsed=clock-first.Time;if(elapsed<.045f)continue;float rise=h.FlickPoint.Y-first.Point.Y,pitch=h.Forward.Y-first.Forward.Y;if(rise>=.075f&&rise/elapsed>=.40f||pitch>=.38f&&pitch/elapsed>=1.4f&&Angle(h.Forward,first.Forward)>=.40f)return true;}
    if(count==64){start=(start+1)%64;count--;}history[(start+count)%64]=new Sample{Point=h.FlickPoint,Forward=h.Forward,Time=clock};count++;return false;
   }
   static Float3 Sub(Float3 a,Float3 b){return new Float3(a.X-b.X,a.Y-b.Y,a.Z-b.Z);}static float Length(Float3 p){return(float)Math.Sqrt(R23WeaponPoseMath.Dot(p,p));}static float Angle(Float3 a,Float3 b){float n=Length(a)*Length(b);return n<.000001f?0:(float)Math.Acos(Math.Max(-1,Math.Min(1,R23WeaponPoseMath.Dot(a,b)/n)));}
  }
  readonly Gun[] guns={new Gun(),new Gun()};readonly IRevisionedAmmoReserve reserve;readonly IAuthorityGate authority;readonly string session,actor;readonly long authorityEpoch;readonly HashSet<string> commands=new HashSet<string>(StringComparer.Ordinal);readonly Queue<string> commandOrder=new Queue<string>();long sequence=-1,tick,epoch;bool retired;int dominant=1;
  public readonly R24DualDefinition Definition;public string InstanceId{get;private set;}public bool Equipped{get;private set;}public bool Retired{get{return retired;}}public int Reserve{get{return reserve.Available;}}public int Loaded{get{return guns[0].Loaded+guns[1].Loaded;}}public long TotalShots{get{return guns[0].Shots+guns[1].Shots;}}public bool ClaimsBothHands{get{return Equipped&&!retired;}}public int DominantHand{get{return dominant;}}
  public R24DualOwner(CommandContext creation,string instance,R24DualDefinition definition,IRevisionedAmmoReserve actualFamilyReserve,IAuthorityGate actualAuthority){if(definition==null||actualFamilyReserve==null||actualAuthority==null||String.IsNullOrEmpty(instance)||instance.Length>128||!actualAuthority.Validate(creation).Accepted||!creation.IsAuthority)throw new ArgumentException("Trusted actual dual instance/authority/reserve required");Definition=definition;InstanceId=instance;reserve=actualFamilyReserve;authority=actualAuthority;session=creation.SessionId;actor=creation.ActorId;authorityEpoch=creation.AuthorityEpoch;tick=creation.Tick;guns[0].Loaded=guns[1].Loaded=definition.Capacity;}
  public bool TryEquip(bool leftFree,bool rightFree,int physicalDominant=1){if(retired||!leftFree||!rightFree||physicalDominant<0||physicalDominant>1)return false;dominant=physicalDominant;Equipped=true;SuspendControls();return true;}
  public void Holster(){Equipped=false;SuspendControls();}public void Retire(){retired=true;Equipped=false;SuspendControls();}
  public void SuspendControls(){epoch++;foreach(var g in guns){g.NeedRelease=true;g.Flick.Reset();g.Spin=.36f;}}
  internal bool ReconcileNetworkAmmo(int left,int right){if(retired||left<0||right<0||left>Definition.Capacity||right>Definition.Capacity)return false;int[] values={left,right};for(int i=0;i<2;i++)if(guns[i].Loaded!=values[i]){guns[i].Loaded=values[i];guns[i].NeedRelease=true;guns[i].Flick.Reset();}return true;}
  public R24DualHandState ReadHand(int side){if(side<0||side>1)throw new ArgumentOutOfRangeException("side");var g=guns[side];return new R24DualHandState{Loaded=g.Loaded,Capacity=Definition.Capacity,PhysicalHand=side==0?dominant:1-dominant,Shots=g.Shots,NeedsAmmo=g.Loaded==0,RequiresTriggerRelease=g.NeedRelease,Cooldown=g.Cooldown,SpinElapsed=g.Spin};}
  public RuleResult Apply(CommandContext c,R24DualFrame f,out R24DualStep result){result=null;if(retired||c.SessionId!=session||c.ActorId!=actor||c.AuthorityEpoch!=authorityEpoch||!c.IsAuthority||c.Tick<tick||f.Sequence<=sequence||String.IsNullOrEmpty(c.CommandId)||commands.Contains(c.CommandId))return RuleResult.Reject("Retired/replayed/foreign dual input");var authorized=authority.Validate(c);if(!authorized.Accepted)return authorized;if(!Finite(f.DeltaSeconds)||f.DeltaSeconds<0||f.DeltaSeconds>.25f||f.DominantHand<0||f.DominantHand>1)return RuleResult.Reject("Finite dual input frame required");tick=c.Tick;sequence=f.Sequence;commands.Add(c.CommandId);commandOrder.Enqueue(c.CommandId);if(commandOrder.Count>256)commands.Remove(commandOrder.Dequeue());
   if(dominant!=f.DominantHand){dominant=f.DominantHand;SuspendControls();}if(!Equipped||!f.Enabled||f.Paused||!f.Focused){SuspendControls();result=new R24DualStep(null,null,null,null);return RuleResult.Accept();}
   string ra,rb;var a=StepGun(c,f,0,out ra);var b=StepGun(c,f,1,out rb);result=new R24DualStep(a,b,ra,rb);return RuleResult.Accept();
  }
  R24DualVolley StepGun(CommandContext c,R24DualFrame f,int side,out string reload){reload=null;var g=guns[side];int physical=side==0?dominant:1-dominant;var h=f.Hand(physical);float dt=f.DeltaSeconds,overrun=g.Cooldown>0?Math.Max(0,Math.Min(Definition.Interval,dt-g.Cooldown)):0;g.Cooldown=Math.Max(0,g.Cooldown-dt);g.Spin=Math.Min(.36f,g.Spin+dt);
   if(!h.Tracked||!h.InputReady||h.Climbing||h.Reserved||f.HeadObstructed||!h.FlickPoint.IsFinite||!h.Forward.IsFinite||!Finite(h.Trigger)){g.NeedRelease=true;g.Flick.Reset();g.Spin=.36f;return null;}
   if(!h.Pressed){g.NeedRelease=false;g.SemiArmed=true;}R24DualVolley volley=null;
   if(h.Pressed&&!g.NeedRelease&&g.Cooldown<=0&&g.Loaded>0&&(Definition.Automatic||g.SemiArmed)&&h.FiringPose.Valid){g.Loaded--;g.Shots++;g.SemiArmed=false;g.Cooldown=Definition.Automatic?Math.Max(.001f,Definition.Interval-overrun):Definition.Interval;volley=new R24DualVolley(this,c,side,physical,g.Shots,h.FiringPose,epoch);if(g.Loaded==0)g.NeedRelease=true;}
   if(f.DesktopReload||g.Flick.Step(h,dt,g.Loaded,g.Spin))reload=Reload(g);return volley;
  }
  string Reload(Gun g){if(g.Loaded>=Definition.Capacity){g.Spin=0;g.Cooldown=Math.Max(g.Cooldown,.36f);g.NeedRelease=true;g.Flick.Reset();return "cosmetic";}int remaining=g.Loaded,returned=reserve.Refund(remaining);if(returned<0||returned>remaining)throw new InvalidOperationException("Actual reserve violated atomic refund contract");g.Loaded-=returned;if(returned<remaining)return "partial_refund";int taken=reserve.Take(Definition.Capacity);if(taken<0||taken>Definition.Capacity)throw new InvalidOperationException("Actual reserve violated atomic take contract");g.Loaded=taken;g.NeedRelease=true;g.Cooldown=Math.Max(g.Cooldown,.36f);g.Spin=0;g.Flick.Reset();return "mag_insert";}
  internal bool Claim(R24DualVolley shot){if(retired||!Equipped||shot.InstanceId!=InstanceId||shot.Epoch!=epoch||shot.Serial<=guns[shot.Side].Committed)return false;guns[shot.Side].Committed=shot.Serial;return true;}
  static bool Finite(float x){return !float.IsNaN(x)&&!float.IsInfinity(x);}
 }
